"""Prepare a separate inert visual Preview; no app bundle, SDK, credentials or deployment."""
from pathlib import Path
import json,hashlib,shutil,html
R=Path('/tmp/narvo-r0-release-20261102/safe-visual-preview');R.mkdir();src=Path('docs/release/emerald-enterprise/after/screenshots');names=['onboarding-pending-en-desktop.png','onboarding-pending-ar-mobile.png','onboarding-ready-en-desktop.png','dashboard-en-desktop.png','dashboard-ar-mobile.png'];names=[n for n in names if(src/n).exists()]
assert len(names)>=4
for name in names:shutil.copyfile(src/name,R/name)
csp="default-src 'none'; img-src 'self'; style-src 'unsafe-inline'; script-src 'none'; connect-src 'none'; form-action 'none'; frame-ancestors 'none'; base-uri 'none'"
(R/'vercel.json').write_text(json.dumps({'framework':None,'buildCommand':'','installCommand':'','outputDirectory':'.','headers':[{'source':'/(.*)','headers':[{'key':'Content-Security-Policy','value':csp},{'key':'X-Robots-Tag','value':'noindex, nofollow'},{'key':'Referrer-Policy','value':'no-referrer'},{'key':'X-Content-Type-Options','value':'nosniff'}]}]},indent=2)+'\n')
figures=''.join(f'<figure><figcaption>{html.escape(n[:-4].replace("-"," "))}</figcaption><a href="{n}"><img src="{n}" alt="Approved synthetic Emerald screen: {html.escape(n[:-4])}"></a></figure>'for n in names)
(R/'index.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NARVO R0 — isolated visual Preview</title><style>body{font:1rem/1.6 system-ui;color:#17332d;background:#f4f7f5;margin:0}main{max-width:1200px;margin:auto;padding:24px;overflow-wrap:anywhere}figure{margin:24px 0;background:white;padding:16px;border:1px solid #789488;border-radius:10px}img{display:block;max-width:100%;height:auto}a{color:#006a52}a:focus-visible{outline:3px solid #006a52;outline-offset:4px}</style><a href="#main">Skip to screenshots</a><main id="main"><h1>NARVO R0 isolated visual Preview</h1><p>Previously approved synthetic screenshots only. No sign-in, application commands, database connection or backend configuration. This package is separate from the functional Production candidate.</p>'+figures+'</main></html>')
manifest={'status':'PREPARED_NOT_DEPLOYED','purpose':'Inert visual Preview only; not functional onboarding acceptance','source':'Approved Emerald evidence, unchanged candidate source hashes verified separately','csp':csp,'javascript_files':0,'forms':0,'credentials':False,'supabase_sdk':False,'hosted_connection':False,'files_sha256':{p.name:hashlib.sha256(p.read_bytes()).hexdigest()for p in R.iterdir()if p.is_file()}}
Path('docs/release/r0-release-execution/safe-preview-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n');print('Inert Preview prepared:',len(manifest['files_sha256']),'static files; no scripts/forms/backend')
